DIAG = [1, 1, 2]  # M_I = J + diag(DIAG); mu = DIAG+1 = [2,2,3]

def sbox(x):
    x2 = x*x % P
    x4 = x2*x2 % P
    return x4*x % P

# Explicit matrices (for cross-check)
M_E = [[2,1,1],[1,2,1],[1,1,2]]              # circ(2,1,1)
M_I = [[2,1,1],[1,2,1],[1,1,3]]              # J + diag([1,1,2])

def matmul(M, s):
    return [ (M[i][0]*s[0] + M[i][1]*s[1] + M[i][2]*s[2]) % P for i in range(3) ]

def matmul_external_shortcut(s):
    t = (s[0]+s[1]+s[2]) % P
    return [ (s[i]+t) % P for i in range(3) ]

def matmul_internal_shortcut(s):
    t = (s[0]+s[1]+s[2]) % P
    # out[i] = sum + DIAG[i]*s[i]
    return [ (t + DIAG[i]*s[i]) % P for i in range(3) ]

def poseidon2_perm(state):
    s = [x % P for x in state]
    # 1. initial external linear layer
    s = matmul_external_shortcut(s)
    # 2. first 4 external (full) rounds
    for r in range(4):
        s = [ (s[i] + RC_EXT[r][i]) % P for i in range(3) ]
        s = [ sbox(s[i]) for i in range(3) ]
        s = matmul_external_shortcut(s)
    # 3. 56 internal (partial) rounds
    for r in range(56):
        s[0] = (s[0] + RC_INT[r]) % P
        s[0] = sbox(s[0])
        s = matmul_internal_shortcut(s)
    # 4. last 4 external (full) rounds
    for r in range(4, 8):
        s = [ (s[i] + RC_EXT[r][i]) % P for i in range(3) ]
        s = [ sbox(s[i]) for i in range(3) ]
        s = matmul_external_shortcut(s)
    return s

